    if ((momentum == NULL) || (field == NULL) || (enabled == NULL) || 
        (excess == NULL) || (command == NULL) || (torque == NULL)) {
        return ADCS_E_NULL;
    }

    *excess = 0.0;
    command->command->x = 0.0;
    command->command->y = 0.0;
    command->command->z = 0.0;
    command->saturated_axes = 0U;
    torque->x = 0.0;
    torque->y = 0.0;
    torque->z = 0.0;

    if (!adcs_is_finite_vec3(momentum) || !adcs_is_finite_vec3(field)) {
        return ADCS_E_RANGE;
    }
    if (!isfinite(start_threshold) || !isfinite(stop_threshold)) {
        return ADCS_E_RANGE;
    }
    if (previous_enabled != 0 && previous_enabled != 1) {
        return ADCS_E_RANGE;
    }
    if (stop_threshold < 0.0) {
        return ADCS_E_RANGE;
    }
    if (stop_threshold >= start_threshold) {
        return ADCS_E_RANGE;
    }

    double norm = adcs_vec3_norm(momentum);

    int curr_enabled = 0;
    double curr_excess = 0.0;

    if (previous_enabled == 0) {
        if (norm < start_threshold) {
            curr_enabled = 0;
            curr_excess = (norm > start_threshold) ? (norm - start_threshold) : 0.0;
        } else {
            curr_enabled = 1;
            curr_excess = norm - stop_threshold;
        }
    } else {
        if (norm <= stop_threshold) {
            curr_enabled = 0;
            curr_excess = (norm > start_threshold) ? (norm - start_threshold) : 0.0;
        } else {
            curr_enabled = 1;
            curr_excess = norm - stop_threshold;
        }
    }

    *enabled = curr_enabled;
    *excess = curr_excess;

    if (curr_enabled == 1) {
        adcs_status_t status = adcs_momentum_unload_dipole(
            momentum, field, gain, dipole_limit, command, torque
        );

        if (status != ADCS_OK) {
            command->command->x = 0.0;
            command->command->y = 0.0;
            command->command->z = 0.0;
            command->saturated_axes = 0U;
            torque->x = 0.0;
            torque->y = 0.0;
            torque->z = 0.0;
            return status;
        }
    }

    return ADCS_OK;
}

