candidates.raw:
    // 1. Null checks
    if ((momentum == NULL) || (field == NULL) || (enabled == NULL) || 
        (excess == NULL) || (command == NULL) || (torque == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Range checks for parameters
    if ((previous_enabled != 0) && (previous_enabled != 1)) {
        return ADCS_E_RANGE;
    }
    if ((!isfinite(start_threshold)) || (!isfinite(stop_threshold))) {
        return ADCS_E_RANGE;
    }
    if (stop_threshold < 0.0) {
        return ADCS_E_RANGE;
    }
    if (stop_threshold >= start_threshold) {
        return ADCS_E_RANGE;
    }
    if (!adcs_is_finite_vec3(momentum)) {
        return ADCS_E_RANGE;
    }
    if (!adcs_is_finite_vec3(field)) {
        return ADCS_E_RANGE;
    }

    // 3. Reset outputs to zero
    *enabled = 0;
    *excess = 0.0;
    command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
    command->saturated_axes = 0U;
    *torque = (adcs_vec3_t){0.0, 0.0, 0.0};

    // 4. Check for null field vector magnitude (degenerate case for torque calc)
    // The requirement says "null momentum/field -> ADCS_E_NULL". 
    // Usually implies zero vector or NULL pointer. Pointer is checked above.
    // Check if field is effectively zero.
    double field_norm = adcs_vec3_norm(field);
    if (field_norm < ADCS_EPS_NORM) {
        return ADCS_E_NULL;
    }

    // 5. Calculate momentum norm
    double norm = adcs_vec3_norm(momentum);

    // 6. Hysteresis logic
    int current_enabled = previous_enabled;

    if (previous_enabled == 0) {
        // Disabled state
        if (norm < start_threshold) {
            current_enabled = 0;
            *excess = 0.0; // max(norm - start, 0) is 0 since norm < start
        } else {
            // norm >= start_threshold
            current_enabled = 1;
            *excess = norm - stop_threshold;
        }
    } else {
        // Enabled state
        if (norm <= stop_threshold) {
            current_enabled = 0;
            *excess = 0.0; // max(norm - start, 0) is 0 since norm <= stop < start
        } else {
            // norm > stop_threshold
            current_enabled = 1;
            *excess = norm - stop_threshold;
        }
    }

    *enabled = current_enabled;

    // 7. Command synthesis if enabled
    if (*enabled) {
        adcs_status_t status = adcs_momentum_unload_dipole(
            momentum, 
            field, 
            gain, 
            dipole_limit, 
            command, 
            torque
        );

        // If it fails, its status is returned with all outputs zero.
        // Outputs were already zeroed in step 3. 
        // We just need to return the error code.
        if (status != ADCS_OK) {
            return status;
        }
    }

    return ADCS_OK;
}

